import RNA, random, multiprocessing as mp, time, sys
target = ".....(((.(..(.(((((.((((.((...)))).))))((((((...)).))))..(((...)))...))).)..).)))...................."
def worker(seed):
    random.seed(seed)
    best_d = 999; best_seq = None
    for _ in range(50):
        start = ''.join(random.choice('ACGU') for _ in range(len(target)))
        seq, d = RNA.inverse_fold(start, target)
        if d == 0:
            st = RNA.fold_compound(seq).mfe()[0]
            if st == target:
                return seq
        if d < best_d:
            best_d = d; best_seq = seq
    return (best_d, best_seq)
if __name__ == '__main__':
    with mp.Pool(48) as p:
        for r in p.imap_unordered(worker, range(480)):
            if isinstance(r, str):
                print('SOLVED', r); sys.stdout.flush(); p.terminate(); break
            else:
                print('best', r[0]); sys.stdout.flush()
